import { z } from 'zod'

// Canonical lowercase UUID, as generated by the device and kept across every hop
const LOWERCASE_UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/

type AssistantRequestSchema = z.ZodObject<
  { request_id: z.ZodString; message: z.ZodString },
  'strict'
>

/**
 * Body of POST /conversations/assistant. Strict: identity and context fields
 * (userId, channelId, history...) are rejected, never applied.
 */
export const buildAssistantRequestSchema = (maxInputChars: number): AssistantRequestSchema =>
  z
    .object({
      request_id: z
        .string()
        .regex(LOWERCASE_UUID_PATTERN, 'request_id debe ser un UUID en minúsculas'),
      message: z
        .string()
        .trim()
        .min(1, 'message no puede estar vacío')
        .max(maxInputChars, `message admite hasta ${maxInputChars} caracteres`),
    })
    .strict()
